import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
void main() => runApp(const ProviderScope(child: WarehouseApp()));
class WarehouseApp extends StatelessWidget { const WarehouseApp({super.key}); @override Widget build(BuildContext context) => MaterialApp.router(title: 'NovaMart Warehouse', theme: ThemeData(colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xff6b58b5)), useMaterial3: true), routerConfig: GoRouter(routes: [GoRoute(path: '/', builder: (_, __) => const WarehouseHome())])); }
class WarehouseHome extends StatelessWidget { const WarehouseHome({super.key}); @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Warehouse operations'), actions: [IconButton(onPressed: () {}, icon: const Icon(Icons.qr_code_scanner))]), body: ListView(padding: const EdgeInsets.all(20), children: [Text('Move stock precisely', style: Theme.of(context).textTheme.displaySmall?.copyWith(fontWeight: FontWeight.w800)), const SizedBox(height: 8), const Text('Inbound, picking, packing, QC, dispatch, returns and cycle counts.'), const SizedBox(height: 24), const Wrap(spacing: 12, runSpacing: 12, children: [WarehouseAction(icon: Icons.download, title: 'Inbound'), WarehouseAction(icon: Icons.shopping_basket_outlined, title: 'Picking'), WarehouseAction(icon: Icons.inventory_2_outlined, title: 'Packing'), WarehouseAction(icon: Icons.verified_outlined, title: 'QC'), WarehouseAction(icon: Icons.local_shipping_outlined, title: 'Dispatch'), WarehouseAction(icon: Icons.assignment_return_outlined, title: 'Returns')]), const SizedBox(height: 24), Card(child: ListTile(leading: const Icon(Icons.security), title: const Text('Every adjustment is maker-checker'), subtitle: const Text('Stock changes use the transaction-safe inventory ledger.'))), FilledButton.icon(onPressed: () => context.go('/'), icon: const Icon(Icons.refresh), label: const Text('Refresh work queue'))])); }
class WarehouseAction extends StatelessWidget { final IconData icon; final String title; const WarehouseAction({required this.icon, required this.title, super.key}); @override Widget build(BuildContext context) => SizedBox(width: 150, child: Card(child: Padding(padding: const EdgeInsets.all(16), child: Column(children: [Icon(icon, size: 30), const SizedBox(height: 8), Text(title)])))); }
